function renderGeneralCensusReadiness(r){
  if(!$('#generalCensusReadinessState'))return;
  r=r||{};
  const state=String(r.state||'UNKNOWN');
  const stateLabel={BLOCKED:'BLOQUEADO · corrija a configuração',RUNNING:'EM EXECUÇÃO · ver Servidor → Atividade',REPORT_FRESH:'RELATÓRIO ATUAL · pronto para leitura',REPORT_STALE:'RELATÓRIO DESATUALIZADO · execute novamente',READY_TO_RUN:'PRONTO PARA EXECUTAR'}[state]||state;
  $('#generalCensusReadinessState').textContent=stateLabel;
  const checks=(r.checks||[]).map(x=>`<div class="general-census-check"><span><b>${esc(x.label||x.key)}</b><br><small>${x.exists?'READY':x.required?'OBRIGATÓRIO':'OPCIONAL'}</small></span><code>${esc(x.path||'não configurado')}</code></div>`);
  checks.push(`<div class="general-census-check"><span><b>Donor clients</b><br><small>${Number(r.donor_client_count||0)} salvos</small></span><code>${(r.donor_clients||[]).map(x=>esc(x.label||'?')).join(', ')||'nenhum'}</code></div>`);
  checks.push(`<div class="general-census-check"><span><b>Donor servers</b><br><small>${Number(r.donor_server_count||0)} salvos</small></span><code>${(r.donor_servers||[]).map(x=>esc(x.label||'?')).join(', ')||'nenhum'}</code></div>`);
  $('#generalCensusChecklist').innerHTML=checks.join('');
  const notices=[];
  (r.blockers||[]).forEach(x=>notices.push(`<div class="general-census-notice blocked"><b>${esc(x.code||'BLOCKED')}</b> · ${esc(x.message||'')}</div>`));
  (r.warnings||[]).forEach(x=>notices.push(`<div class="general-census-notice warning"><b>${esc(x.code||'WARNING')}</b> · ${esc(x.message||'')}</div>`));
  (r.notes||[]).forEach(x=>notices.push(`<div class="general-census-notice note"><b>${esc(x.code||'INFO')}</b> · ${esc(x.message||'')}</div>`));
  if(r.freshness==='FRESH_CONFIG'&&r.report)notices.unshift(`<div class="general-census-notice note"><b>RELATÓRIO ATUAL</b> · ${Number(r.report.candidate_count||0).toLocaleString()} candidatos · estado ${esc(r.report.census_state||r.report.status||'PASS')}.</div>`);
  $('#generalCensusNotices').innerHTML=notices.join('')||'<div class="general-census-notice note">Configuração pronta.</div>';
  $('#generalCensusCommand').textContent=r.command_preview||'Comando indisponível até completar os roots obrigatórios.';
  const copy=$('#copyGeneralCensusCommandBtn');if(copy)copy.disabled=!r.command;
  const run=$('#generalCensusBtn');if(run){run.disabled=!r.can_run||state==='RUNNING';run.title=!r.can_run?'Corrija os roots/donors indicados antes de executar.':state==='RUNNING'?'Já existe um Censo geral iniciado pela GUI em execução.':'Executar Censo geral usando exatamente a configuração salva acima.'}
}
