    $('#clientRegistryState').textContent=reg.status||'SEM RELATÓRIO';
    $('#clientRegistrySummary').innerHTML=contractPairs({'Records':reg.record_count??'—','Client root':reg.client_root||d.client_root||'—','Famílias físicas':compactCounts(c.physical_family_counts),'Categorias':compactCounts(c.category_counts),'Visibilidade':compactCounts(c.visibility_counts)});
