async function loadClientEnrichmentIssues(){
  if(!$('#clientEnrichmentRows'))return;
  const state=$('#clientEnrichmentIssueState')?.value||'',group=$('#clientEnrichmentIssueGroup')?.value||'',kind=$('#clientEnrichmentIssueKind')?.value||'',q=$('#clientEnrichmentSearch')?.value.trim()||'';
  try{
    const qs=new URLSearchParams({state,group,kind,q,limit:'500'}),d=await api('/api/client/report?'+qs);
    setCountOptions($('#clientEnrichmentIssueState'),d.state_counts||{},'Todos os estados');
    setCountOptions($('#clientEnrichmentIssueGroup'),d.group_counts||{},'Todos os grupos');
    setCountOptions($('#clientEnrichmentIssueKind'),d.kind_counts||{},'Todos os tipos');
    $('#clientEnrichmentCount').textContent=d.status==='NO_REPORT'?'Sem relatório. Execute “Analisar enrichment client”.':`${esc(d.assessment_status||'REVIEW_REQUIRED')} · ${Number(d.filtered_rows||0).toLocaleString()} de ${Number(d.total_rows||0).toLocaleString()} gaps acionáveis`;
    const rows=d.rows||[];
    $('#clientEnrichmentRows').innerHTML=rows.length?rows.map((row,i)=>{const why=(row.reasons||[]).join(' · '),act=row.suggested_action?` · ação ${row.suggested_action}`:'',ev=row.evidence?` · ${row.evidence}`:'';return `<tr data-client-enrichment-row="${i}"><td><span class="status-chip ${statusClass(row.state)}">${esc(row.state||'REVIEW')}</span></td><td>${esc(row.group||'—')}</td><td>${esc(row.kind||'—')}</td><td class=path title="${esc(row.path||row.target||'')}">${esc(row.path||row.display_name||row.target||'—')}</td><td title="${esc(why+act+ev)}">${esc((why+act+ev).slice(0,260)||'—')}</td></tr>`}).join(''):'<tr><td colspan="5" class="empty">Nenhum gap corresponde aos filtros atuais.</td></tr>';
    $$('[data-client-enrichment-row]').forEach(tr=>tr.onclick=async()=>{const row=rows[Number(tr.dataset.clientEnrichmentRow)],path=row?.path;if(!path)return;try{setTab('catalog');await selectAsset(path)}catch(e){toast('O target do gap não é um asset direto do catálogo: '+e.message)}});
  }catch(e){$('#clientEnrichmentRows').innerHTML=`<tr><td colspan="5" class="empty">${esc(e.message)}</td></tr>`;$('#clientEnrichmentCount').textContent='Erro ao carregar enrichment'}
}

