    const d=await api('/api/client/analyze',{method:'POST',body:{}});S.job=d.job.id;S.clientJob=d.job.id;$('#clientEnrichmentState').textContent='QUEUED · client_enrichment';toast('Client enrichment iniciado');switchClientWorkflow('activity');await loadClientActivity();showClientJob(d.job.id)
