async function armBuildForEnhancement(){if(S.boot.write_armed)return true;const phrase=prompt('Para gerar milhares de candidatos no workspace, digite exatamente ARM BUILD WRITES:','');if(phrase===null)return false;try{const d=await api('/api/safety/arm',{method:'POST',body:{confirm:phrase,seconds:3600}});S.boot.write_armed=!!d.write_armed;S.boot.write_armed_until=d.write_armed_until||0;renderArm();return S.boot.write_armed}catch(e){toast(e.message);return false}}
async function armDeployForEnhancement(){if(S.boot.deploy_armed)return true;const phrase=prompt('Esta ação escreve em massa no client com backup/hash/rollback. Digite exatamente ARM CLIENT DEPLOY:','');if(phrase===null)return false;try{const d=await api('/api/safety/deploy-arm',{method:'POST',body:{confirm:phrase,seconds:900}});S.boot.deploy_armed=!!d.deploy_armed;S.boot.deploy_armed_until=d.deploy_armed_until||0;return S.boot.deploy_armed}catch(e){toast(e.message);return false}}
async function runEnhancementBatch(mode){try{let endpoint='',body={};if(mode==='run'){if(!(await armBuildForEnhancement()))return;if(!confirm('Gerar enhancement AI para TODAS as texturas suportadas do client, incluindo UI/atlases?\n\nIsto pode consumir muito tempo e espaço em disco. O client fonte não será alterado nesta etapa.'))return;const scale=prompt('Escala global: 2, 3 ou 4','4');if(scale===null)return;if(!['2','3','4'].includes(scale.trim())){toast('Use 2, 3 ou 4');return}endpoint='/api/enhancement/batch-run';body={scale:scale.trim(),backend:'realesrgan',profile:'detail',gpu:0,model:'realesrgan-x4plus'}}else if(mode==='resume'){if(!(await armBuildForEnhancement()))return;if(!confirm('Retomar o último run de enhancement? Candidates já validados por hash serão reutilizados; falhas/pendentes serão processados novamente.'))return;endpoint='/api/enhancement/batch-resume'}else if(mode==='publish'){if(!(await armDeployForEnhancement()))return;if(!confirm('PUBLICAR o último lote completo de enhancement no client?\n\nAntes da primeira escrita, TODOS os candidates serão verificados contra o hash atual. Cada asset terá backup próprio. Uma falha no meio dispara rollback automático do que este lote já publicou.'))return;endpoint='/api/enhancement/batch-publish'}else if(mode==='restore'){if(!(await armDeployForEnhancement()))return;if(!confirm('DESFAZER o último lote de enhancement publicado?\n\nO restore só começa se todos os assets ainda estiverem exatamente no hash publicado e todos os backups estiverem válidos.'))return;endpoint='/api/enhancement/batch-restore'}else return;const d=await api(endpoint,{method:'POST',body});S.job=d.job.id;S.clientJob=d.job.id;if(mode!=='run'){S.boot.deploy_armed=false;S.boot.deploy_armed_until=0}$('#clientEnhancementBatchState').textContent=`QUEUED · ${d.mode}`;toast(mode==='run'?'Enhancement global iniciado':mode==='resume'?'Retomada do enhancement iniciada':mode==='publish'?'Publicação do lote iniciada':'Rollback do lote iniciado');switchClientWorkflow('activity');await loadClientActivity();showClientJob(d.job.id)}catch(e){toast(e.message)}}
async function loadClientCensus(){if(!$('#clientCensusRows'))return;const decision=$('#clientCensusDecision')?.value||'',family=$('#clientCensusFamily')?.value||'',q=$('#clientCensusSearch')?.value.trim()||'';try{const qs=new URLSearchParams({side:'CLIENT',decision,family,q,limit:'300'});const d=await api('/api/general-census?'+qs);const summary=d.summary||{};setCountOptions($('#clientCensusDecision'),summary.decision_counts||{},'Todas as decisões');setCountOptions($('#clientCensusFamily'),summary.physical_family_counts||{},'Todas as famílias');const freshness=d.freshness?` · ${d.freshness}`:'';$('#clientCensusCount').textContent=d.status==='NOT_RUN'?'Sem relatório. Execute Censo geral client.':`${Number(d.filtered_rows||0).toLocaleString()} candidatos client${freshness}`;const rows=d.rows||[];$('#clientCensusRows').innerHTML=rows.length?rows.map(row=>{const baseEv=row.reachability_evidence||row.review_evidence||row.manifest_evidence||row.source_evidence||row.reason||'—';const bundle=row.recovery_bundle_status?`Bundle ${row.recovery_bundle_status} · members ${row.recovery_bundle_member_count||0} · missing ${row.recovery_bundle_missing_count||0}`:'';const ev=bundle?`${bundle} · ${baseEv}`:baseEv;const strong=String(row.required_by_reachable_root).toLowerCase()==='true';return `<tr data-client-census-path="${esc(row.path||'')}"><td><span class="status-chip ${strong?'pass':'review'}">${esc(row.decision||'REVIEW')}</span></td><td>${esc(row.physical_family||'—')}</td><td>${esc(row.category||'—')}</td><td class=path title="${esc(row.path||'')}">${esc(row.path||'—')}</td><td title="${esc(ev)}">${esc(String(ev).slice(0,220))}</td></tr>`}).join(''):'<tr><td colspan="5" class="empty">Nenhum candidato client corresponde aos filtros atuais.</td></tr>';$$('[data-client-census-path]').forEach(tr=>tr.onclick=async()=>{const path=tr.dataset.clientCensusPath;if(!path)return;try{setTab('catalog');await selectAsset(path)}catch(e){toast('Path do censo não está no catálogo atual: '+e.message)}})}catch(e){$('#clientCensusRows').innerHTML=`<tr><td colspan="5" class="empty">${esc(e.message)}</td></tr>`;$('#clientCensusCount').textContent='Erro ao carregar censo client'}}
function renderContractConfigFeedback(issues=[],message=''){
  const box=$('#contractConfigFeedback');if(!box)return;
  if(!issues.length&&!message){box.classList.add('hidden');box.innerHTML='';return}
  box.classList.remove('hidden');
  if(issues.length){
    const sideName=s=>s==='client'?'Donor client':s==='server'?'Donor server':'Configuração';
    box.classList.remove('ok');box.classList.add('error');
    box.innerHTML=`<b>Não foi salvo.</b><p>Corrija ${issues.length===1?'o erro abaixo':'os erros abaixo'}; nenhuma parte da configuração foi alterada.</p>${issues.map(x=>`<div class="contract-feedback-row"><strong>${esc(x.line?`${sideName(x.side)} · linha ${x.line}`:(x.field==='source_root'?'Source Summit':x.field==='reference_source_root'?'Source EU de referência':sideName(x.side)))}</strong><span>${esc(x.message||x.code||'Entrada inválida')}</span>${x.input?`<code>${esc(x.input)}</code>`:''}</div>`).join('')}<p class=micro>Formato aceito: <code>LABEL=/caminho</code> ou uma linha completa copiada do CLI, por exemplo <code>--donor-client 'DONOR1=/caminho com espaços'</code>. Labels: letras, números, <code>_</code> e <code>-</code>.</p>`;
  }else{
    box.classList.remove('error');box.classList.add('ok');box.innerHTML=`<b>${esc(message||'Configuração validada e salva.')}</b>`;
    setTimeout(()=>{if(box.classList.contains('ok')){box.classList.add('hidden');box.innerHTML=''}},3500);
  }
}
async function saveContractRoots(){
  const source=$('#sourceRootInput').value.trim(),reference=$('#referenceSourceRootInput').value.trim();
  const donors=$('#contractDonorsInput').value.split(/\r?\n/),serverDonors=$('#contractServerDonorsInput')?$('#contractServerDonorsInput').value.split(/\r?\n/):[];
  renderContractConfigFeedback();
  try{
    const d=await api('/api/contracts/config',{method:'POST',body:{source_root:source,reference_source_root:reference,donor_clients:donors,donor_servers:serverDonors}});
    S.boot.source_root=d.source_root;S.boot.reference_source_root=d.reference_source_root;S.boot.contract_donor_clients=d.donor_clients||[];S.boot.contract_donor_servers=d.donor_servers||[];
    renderContractConfigFeedback([],`Configuração salva · ${d.donor_clients?.length||0} donor client(s) · ${d.donor_servers?.length||0} donor server(s).`);
    toast('Fontes e donors validados e salvos');await loadContracts();
  }catch(e){
    const issues=e.payload?.issues||[];renderContractConfigFeedback(issues,issues.length?'':e.message);if(!issues.length)toast(e.message);
  }
}
async function pollContractJob(id){clearInterval(S.contractPoll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#contractState').textContent=`${j.status} · ${j.action}`;if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.contractPoll);S.contractPoll=null;await loadContracts();if($('#clientEnrichmentState'))await loadClientEnrichment();toast(j.status==='PASS'?'Asset Contracts atualizados':`Asset Contracts: ${j.status}`)}}catch(e){clearInterval(S.contractPoll);S.contractPoll=null;toast(e.message)}};await poll();if(S.contractPoll===null&&/^(PASS|FAIL|ERROR|CANCELLED)/.test($('#contractState').textContent))return;S.contractPoll=setInterval(poll,1200)}
async function runContractAnalysis(mode,surface='server'){
  try{
    const d=await api('/api/contracts/analyze',{method:'POST',body:{mode,surface}});S.job=d.job.id;
    const msg=mode==='source'?'Leitura de contratos do source iniciada':mode==='aggregate_player_classes'?'Agregação staging das 10 classes iniciada':mode==='aggregate_summit'?'Agregação completa Summit iniciada':mode==='general_census'?'Censo geral plan-only iniciado':'Audit das 10 classes iniciado';
    if(surface==='server'){
      S.serverJob=d.job.id;if(mode==='general_census'&&d.preflight)renderGeneralCensusReadiness({...d.preflight,state:'RUNNING',can_run:true,active_job:d.job});
      toast(msg);switchServerWorkflow('activity');await loadServerActivity();showServerJob(d.job.id);
    }else{
      S.clientJob=d.job.id;if($('#clientEnrichmentState'))$('#clientEnrichmentState').textContent=`QUEUED · contracts_${mode}`;toast(msg);switchClientWorkflow('activity');await loadClientActivity();showClientJob(d.job.id);
    }
  }catch(e){toast(e.message)}
}
async function pollServerJob(id){const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#serverRootStatus').textContent=`${j.status} · ${j.action}`;if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.serverPoll);S.serverPoll=null;await loadServer();if($('#clientEnrichmentState'))await loadClientEnrichment();toast(j.status==='PASS'?'Análise server concluída':`Análise server: ${j.status}`)}}catch(e){clearInterval(S.serverPoll);S.serverPoll=null;toast(e.message)}};await poll();if(S.serverPoll==null&&$('#serverRootStatus').textContent.match(/^(PASS|FAIL|ERROR|CANCELLED)/))return;clearInterval(S.serverPoll);S.serverPoll=setInterval(poll,1200)}
async function runServerAnalysis(mode,surface='server'){
  try{
    const d=await api('/api/server/analyze',{method:'POST',body:{mode,surface}});S.job=d.job.id;
    if(surface==='server'){
      S.serverJob=d.job.id;toast(`Análise server ${mode} iniciada`);switchServerWorkflow('activity');await loadServerActivity();showServerJob(d.job.id);
    }else{
      S.clientJob=d.job.id;if($('#clientEnrichmentState'))$('#clientEnrichmentState').textContent=`QUEUED · server_${mode}`;toast(`Análise ${mode} iniciada`);switchClientWorkflow('activity');await loadClientActivity();showClientJob(d.job.id);
    }
  }catch(e){toast(e.message)}
}
function compareOpenPath(report,row){const cr=S.boot?.client_root;if(report.left_root===cr&&row.left_path)return row.left_path;if(report.right_root===cr&&row.right_path)return row.right_path;return null}
function renderCompareReport(r){const s=r.summary||{},rows=(r.rows||[]),shown=rows.slice(0,500);$('#compareStatus').textContent=`PASS · ${Number(s.difference_path_count||0).toLocaleString()} diferenças`;const metrics=[['Esquerda',s.left_file_count],['Direita',s.right_file_count],['Só esquerda',s.only_left_count],['Só direita',s.only_right_count],['Diferentes',s.difference_path_count]];const table=shown.length?`<div class=compare-table><table><thead><tr><th>Status</th><th>Categoria</th><th>Ext</th><th>Path</th><th>Tamanho A</th><th>Tamanho B</th></tr></thead><tbody>${shown.map(row=>{const open=compareOpenPath(r,row);const path=row.left_path||row.right_path||row.key;return `<tr ${open?`data-open-asset="${esc(open)}" class=compare-row-clickable`:''}><td><span class="status ${esc(row.status)}">${esc(row.status)}</span></td><td>${esc(row.category||'—')}</td><td>${esc(row.extension||'—')}</td><td class=path title="${esc(path)}">${esc(path)}</td><td>${row.left_size==null?'—':fmtBytes(row.left_size)}</td><td>${row.right_size==null?'—':fmtBytes(row.right_size)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class=empty>Nenhuma linha para exibir com os filtros atuais.</div>';$('#compareResult').innerHTML=`<div class=compare-summary>${metrics.map(([label,value])=>`<div class=metric><b>${Number(value||0).toLocaleString()}</b><span>${esc(label)}</span></div>`).join('')}</div><div class=compare-note>${r.content_hash?'SHA-256 ativo':'Comparação rápida por path/tamanho'} · ${r.differences_only?'somente diferenças':'todas as linhas'} · exibindo ${shown.length.toLocaleString()} de ${rows.length.toLocaleString()} linhas do relatório.</div>${table}`;$$('[data-open-asset]').forEach(x=>x.onclick=async()=>{setTab('catalog');await selectAsset(x.dataset.openAsset)})}
async function loadCompareReport(name){const d=await api('/api/report?name='+encodeURIComponent(name));renderCompareReport(d.report)}
async function pollTreeCompare(id,name){clearInterval(S.comparePoll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#compareStatus').textContent=`${j.status} · ${j.action}`;if(j.status==='PASS'){clearInterval(S.comparePoll);S.comparePoll=null;await loadCompareReport(name);toast('Comparação concluída')}else if(['FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.comparePoll);S.comparePoll=null;$('#compareResult').innerHTML=`<pre>${esc(j.tail||j.command_display)}</pre>`;toast(j.status==='CANCELLED'?'Comparação cancelada':'Comparação falhou')}}catch(e){clearInterval(S.comparePoll);S.comparePoll=null;$('#compareStatus').textContent='Erro ao consultar tarefa';toast(e.message)}};await poll();if(['PASS','FAIL','ERROR','CANCELLED'].some(x=>$('#compareStatus').textContent.startsWith(x)))return;S.comparePoll=setInterval(poll,1000)}
async function runTreeCompare(){const left=$('#compareLeft').value.trim(),right=$('#compareRight').value.trim();if(!left||!right){toast('Informe as duas árvores');return}try{const d=await api('/api/tree-compare',{method:'POST',body:{left,right,hash:$('#compareHash').checked,case_sensitive:$('#compareCase').checked,differences_only:$('#compareDiffOnly').checked,extensions:$('#compareExt').value.trim(),category:$('#compareCategory').value,path_contains:$('#comparePath').value.trim()}});S.job=d.job.id;S.compareOutput=String(d.output||'').split('/').pop();$('#compareStatus').textContent='QUEUED · tree_compare';$('#compareResult').innerHTML='<div class=empty>Comparação em andamento…</div>';toast('Comparação iniciada');pollTreeCompare(d.job.id,S.compareOutput)}catch(e){toast(e.message)}}
async function runMonsterNpcCensus(){try{const d=await api('/api/monster-npc-census',{method:'POST',body:{refresh_census:false}});S.job=d.job.id;toast('Censo Monster/NPC iniciado');setTab('catalog');showJob(d.job.id)}catch(e){toast(e.message)}}
function legacyStatusChip(status){const v=String(status||'—'),c=/(NOT_PROVED|REVIEW|AMBIGUOUS|MISSING|UNRESOLVED|HASH_MISMATCH)/.test(v)?'review':/(PASS|CLOSED|RESOLVED|MATCH|SOURCE_VERIFIED|CONFIRMED)/.test(v)?'pass':'blocked';return `<span class="status-chip ${c}">${esc(v)}</span>`}
function legacyReqStatus(r){if(r.status==='READY')return '<span class="status-chip pass">READY</span>';if(r.status==='MISSING'||r.status==='CLIENT_NOT_CONFIGURED')return `<span class="status-chip ${r.required?'blocked':'review'}">${esc(r.status)}</span>`;return r.required?'<span class="status-chip pass">NECESSÁRIO</span>':'<span class="status-chip review">OPCIONAL</span>'}
function renderLegacyGuideDomain(id,d){const el=$(id);if(!el||!d)return;el.innerHTML=`<div class=legacy-guide-summary><p>${esc(d.summary||'')}</p>${d.hard_block?`<div class=legacy-hard-block><b>Limite atual</b><span>${esc(d.hard_block)}</span></div>`:''}</div><h3>O que você precisa</h3><div class=legacy-requirement-list>${(d.requirements||[]).map(r=>`<div class=legacy-requirement><div>${legacyReqStatus(r)}<b>${esc(r.label)}</b>${r.required?'':'<small>opcional</small>'}</div><p>${esc(r.detail||'')}</p></div>`).join('')}</div>${(d.required_fields||[]).length?`<div class=legacy-field-list><b>Campos mínimos do CREATE</b><code>${esc(d.required_fields.join(', '))}</code></div>`:''}${(d.optional||[]).length?`<div class=legacy-field-list><b>Também suportado</b><span>${esc(d.optional.join(' · '))}</span></div>`:''}`}
async function loadLegacyAuthoringGuide(){try{const d=await api('/api/legacy-authoring/guide'),g=d.result||{};S.legacyGuide=g;renderLegacyGuideDomain('#legacyGuideItem',g.domains?.ITEM);renderLegacyGuideDomain('#legacyGuideMonster',g.domains?.MONSTER);renderLegacyGuideDomain('#legacyGuideNpc',g.domains?.NPC);renderLegacyGuideDomain('#legacyGuideMap',g.domains?.MAP)}catch(e){['#legacyGuideItem','#legacyGuideMonster','#legacyGuideNpc','#legacyGuideMap'].forEach(id=>{if($(id))$(id).innerHTML=`<div class=empty>${esc(e.message)}</div>`})}}
