function configureLegacyEditorForTask(task){const sel=$('#legacyAuthoringKind'),kinds=legacyKindsForTask(task);if(!sel)return;if(!kinds.length){sel.innerHTML='';return}const current=sel.value;sel.innerHTML=kinds.map(k=>`<option value="${k}">${esc(({ITEM:'ITEM',MONSTER:'MONSTER',NPC:'NPC',SPM:'SPM',SPP:'SPP',SPC:'SPC'})[k])}</option>`).join('');if(kinds.includes(current))sel.value=current;else sel.value=kinds[0];sel.classList.toggle('hidden',kinds.length===1)}
function syncLegacyAuthoringUi(){const kind=$('#legacyAuthoringKind')?.value||'',mode=$('#legacyAuthoringMode')?.value||'EDIT';if($('#legacyAuthoringTitle'))$('#legacyAuthoringTitle').textContent=legacyAuthoringTitle(kind,mode);const itemHelper=$('#legacyAuthoringItemHelper');if(itemHelper)itemHelper.classList.toggle('hidden',!['MONSTER','NPC'].includes(kind));const entityHelper=$('#legacyAuthoringEntityHelper');if(entityHelper)entityHelper.classList.toggle('hidden',!['SPM','SPC'].includes(kind));syncLegacyAuthoringCatalogHelper();const pub=$('#legacyAuthoringPublishBtn');if(pub){pub.disabled=!S.legacyAuthoringManifest;pub.title=S.legacyAuthoringManifest?'Publicar o manifest staged desta tarefa':'Faça Stage nesta tarefa antes de publicar'}}
function mountLegacyEditor(task){const editor=$('#legacyAuthoringPanel'),parking=$('#legacyAuthoringParking');if(!editor)return;const kinds=legacyKindsForTask(task);if(!kinds.length){saveLegacyEditorState();if(parking)parking.appendChild(editor);editor.classList.add('hidden');S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();return}const mount=document.querySelector(`[data-legacy-editor-mount="${task}"]`);if(!mount)return;configureLegacyEditorForTask(task);mount.appendChild(editor);editor.classList.remove('hidden');const st=S.legacyEditorState?.[task];if(st){if(kinds.includes(st.kind))$('#legacyAuthoringKind').value=st.kind;$('#legacyAuthoringMode').value=st.mode||'EDIT';$('#legacyAuthoringPath').value=st.path||'';$('#legacyAuthoringSpec').value=st.spec||'';$('#legacyAuthoringResult').textContent=st.result||'';if($('#legacyAuthoringState'))$('#legacyAuthoringState').textContent=st.state||'';S.legacyAuthoringManifest=st.manifest||null}else{S.legacyAuthoringManifest=null;$('#legacyAuthoringPath').value=legacyAuthoringDefaultPath($('#legacyAuthoringKind').value);loadLegacyAuthoringTemplate()}syncLegacyAuthoringUi()}
