function openLegacyAuthoring(kind,mode){kind=String(kind||'ITEM').toUpperCase();mode=String(mode||'EDIT').toUpperCase();const task=legacyTaskForKind(kind);switchLegacyTask(task);configureLegacyEditorForTask(task);$('#legacyAuthoringKind').value=kind;$('#legacyAuthoringMode').value=mode;$('#legacyAuthoringPath').value=legacyAuthoringDefaultPath(kind);S.legacyAuthoringManifest=null;loadLegacyAuthoringTemplate();syncLegacyAuthoringUi();$('#legacyAuthoringPanel')?.scrollIntoView({behavior:'smooth',block:'start'})}
