function updateLegacyInventoryIdentities(){const store=$('#legacyInventoryStore')?.value||'userdata',rows=store==='warehouse'?(S.legacySelections?.accounts||[]):(S.legacySelections?.characters||[]);legacySelectOptions($('#legacyInventoryKey'),rows,{placeholder:store==='warehouse'?'Selecione a conta':'Selecione o personagem'})}
function legacyDatabaseFor(capability){const db=S.legacyOpsStatus?.database||{},sel=$('#legacyDatabasePath'),current=sel?.value||db.path||'',candidates=db.candidates||[],row=candidates.find(x=>x.path===current);if(row?.capabilities?.[capability])return current;const best=candidates.find(x=>x.capabilities?.[capability]);if(best){if(sel)sel.value=best.path;return best.path}return current}
function semanticCatalog(){return S.legacySelections?.authoring_catalog||{}}
function legacyAuthoringCatalogRows(kind){kind=String(kind||'').toUpperCase();const c=semanticCatalog();if(kind==='ITEM')return c.items||[];if(kind==='MONSTER')return c.mobs||[];if(kind==='NPC')return c.npcs||[];if(['SPM','SPP','SPC'].includes(kind))return c.maps||[];return []}
function legacyAuthoringCatalogPath(row,kind){if(!row)return'';kind=String(kind||'').toUpperCase();if(kind==='SPM')return row.logical_spm||'';if(kind==='SPP')return row.logical_spp||'';if(kind==='SPC')return row.logical_spc||'';return row.logical_path||''}
function legacyCatalogLabel(row){if(!row)return'';const amb=row.visible_name_ambiguous?' ⚠ nome ambíguo':'';const conf=row.confidence?` · ${row.confidence}`:'';return `${row.display||row.display_name||row.canonical_id}${amb}${conf}`}
function syncLegacyAuthoringCatalogHelper(){const kind=$('#legacyAuthoringKind')?.value||'',target=$('#legacyAuthoringCatalogEntry'),meta=$('#legacyAuthoringCatalogMeta');if(target){const rows=legacyAuthoringCatalogRows(kind).map(x=>({value:x.canonical_id,label:legacyCatalogLabel(x)}));legacySelectOptions(target,rows,{placeholder:['SPM','SPP','SPC'].includes(kind)?'Mapa / stage mapeado':'Nome visível → identidade canônica'})}if(meta){const counts=S.legacySelections?.semantic_catalog?.counts||{};meta.textContent=kind==='ITEM'?`${Number(counts.items||0).toLocaleString()} itens`:kind==='MONSTER'?`${Number(counts.mobs||0).toLocaleString()} mobs`:kind==='NPC'?`${Number(counts.npcs||0).toLocaleString()} NPCs`:['SPM','SPP','SPC'].includes(kind)?`${Number(counts.maps||0).toLocaleString()} mapas · ${Number(counts.spawn_stages||0).toLocaleString()} stages/spawns`:''}const entity=$('#legacyAuthoringEntityRef');if(entity){let rows=[];let placeholder='Entidade relacionada';if(kind==='SPM'){rows=(semanticCatalog().mobs||[]).map(x=>({value:x.canonical_id,label:legacyCatalogLabel(x)}));placeholder='Mob para actor/spawn'}else if(kind==='SPC'){rows=(semanticCatalog().npcs||[]).map(x=>({value:x.canonical_id,label:legacyCatalogLabel(x)}));placeholder='NPC para placement SPC'}legacySelectOptions(entity,rows,{placeholder})}}
function renderLegacySelections(d){S.legacySelections=d||{};const runtimeItems=(d?.items||[]).map(x=>({value:x.code,label:x.display||x.code}));['#legacyItemCode','#legacyPostboxItem'].forEach(id=>legacySelectOptions($(id),runtimeItems,{placeholder:'Selecione o item · código — nome'}));const semanticItems=(d?.authoring_catalog?.items||[]).map(x=>({value:x.canonical_id,label:legacyCatalogLabel(x)}));legacySelectOptions($('#legacyAuthoringItemCode'),semanticItems,{placeholder:'Item relacionado: nome — código — canonical id'});const chars=d?.characters||[],accounts=d?.accounts||[];['#legacyCharacterName','#legacyPostboxCharacter','#legacyBPRankCharacter'].forEach(id=>legacySelectOptions($(id),chars,{placeholder:'Selecione o personagem'}));['#legacyAccountName','#legacyPostboxAccount','#legacyBlockAccount'].forEach(id=>legacySelectOptions($(id),accounts,{placeholder:'Selecione a conta'}));updateLegacyInventoryIdentities();syncLegacyAuthoringCatalogHelper()}
async function loadLegacySelections(refresh=false){try{const d=await api('/api/legacy-ops/selections'+(refresh?'?refresh=1':''));renderLegacySelections(d.result||d);return d.result||d}catch(e){toast('Listas Legacy: '+e.message);return null}}
function legacySelectedItem(value){const v=String(value||'');return (semanticCatalog().items||[]).find(x=>String(x.canonical_id||'').toLowerCase()===v.toLowerCase())||(S.legacySelections?.items||[]).find(x=>String(x.code||'').toUpperCase()===v.toUpperCase())||null}
function legacySelectedCatalogEntry(){const id=$('#legacyAuthoringCatalogEntry')?.value||'';return legacyAuthoringCatalogRows($('#legacyAuthoringKind')?.value||'').find(x=>String(x.canonical_id||'').toLowerCase()===String(id).toLowerCase())||null}
async function useLegacyCatalogEntry(){const row=legacySelectedCatalogEntry();if(!row){toast('Selecione um registro do catálogo semântico');return}const kind=$('#legacyAuthoringKind')?.value||'ITEM',mode=$('#legacyAuthoringMode')?.value||'EDIT';let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch{spec=legacyAuthoringTemplate()}spec.kind=kind;spec.mode=mode;spec.semantic_ref={canonical_id:row.canonical_id,category:row.category,display_name:row.display_name,internal_name:row.internal_name};const mappedPath=legacyAuthoringCatalogPath(row,kind);if(mappedPath){$('#legacyAuthoringPath').value=mappedPath;spec.path=mappedPath}if(kind==='ITEM'){if(mode==='CREATE'){const fields=spec.fields||(spec.payload?.fields)||(spec.fields={});fields.code=row.code||row.internal_name||'';if(row.display_name)fields.name=row.display_name}}else if(kind==='MONSTER'){if(mode==='CREATE'){spec.payload=spec.payload||{fields:{},drops:[]};spec.payload.fields=spec.payload.fields||{};spec.payload.fields.name=row.display_name||row.internal_name||'';if(row.model_file)spec.payload.fields.model_file=row.model_file;if(row.level!=null)spec.payload.fields.level=row.level}}else if(kind==='NPC'){if(mode==='CREATE'){spec.payload=spec.payload||{fields:{},dialogs:[],shops:{weapon:[],defence:[],etc:[]}};spec.payload.fields=spec.payload.fields||{};spec.payload.fields.name=row.display_name||row.internal_name||'';if(row.model_file)spec.payload.fields.model_file=row.model_file}}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);$('#legacyAuthoringState').textContent=`${kind} · ${row.display_name||row.canonical_id} · ${row.confidence||'sem confidence'}`;if(mode==='EDIT'&&mappedPath)await inspectLegacyAuthoring();else toast(`Mapeamento ${row.canonical_id} aplicado ao CREATE`)}
function addLegacySemanticRelatedRef(spec,role,row){if(!row?.canonical_id)return;spec.semantic_related_refs=Array.isArray(spec.semantic_related_refs)?spec.semantic_related_refs:[];if(!spec.semantic_related_refs.some(x=>String(x?.role||'').toUpperCase()===String(role).toUpperCase()&&String(x?.canonical_id||'').toLowerCase()===String(row.canonical_id).toLowerCase()))spec.semantic_related_refs.push({role,canonical_id:row.canonical_id})}
function insertLegacyItemIntoSpec(){const selected=$('#legacyAuthoringItemCode')?.value||'';if(!selected){toast('Selecione um item relacionado');return}const item=legacySelectedItem(selected);const code=String(item?.code||item?.internal_name||selected);let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch(e){toast('JSON inválido: '+e.message);return}const kind=$('#legacyAuthoringKind')?.value||'ITEM';if(kind==='MONSTER'){if(spec.payload){spec.payload.drops=spec.payload.drops||[];if(!spec.payload.drops.length)spec.payload.drops.push({percentage:100,items:[code]});else{const row=spec.payload.drops[0];row.items=Array.isArray(row.items)?row.items:[];if(!row.items.includes(code))row.items.push(code)}}else{spec.patch=spec.patch||{};spec.patch.drops=spec.patch.drops||[{percentage:100,items:[]}];const row=spec.patch.drops[0];row.items=Array.isArray(row.items)?row.items:[];if(!row.items.includes(code))row.items.push(code)}addLegacySemanticRelatedRef(spec,'ITEM_REFERENCE',item)}else if(kind==='NPC'){const root=spec.payload||spec.patch||(spec.patch={});root.shops=root.shops||{weapon:[],defence:[],etc:[]};root.shops.weapon=Array.isArray(root.shops.weapon)?root.shops.weapon:[];if(!root.shops.weapon.includes(code))root.shops.weapon.push(code);addLegacySemanticRelatedRef(spec,'ITEM_REFERENCE',item)}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);toast(`${item?.display_name||code} (${code}) inserido no spec`)}
function insertLegacyEntityIntoSpec(){const kind=$('#legacyAuthoringKind')?.value||'',id=$('#legacyAuthoringEntityRef')?.value||'';if(!id){toast('Selecione a entidade relacionada');return}const rows=kind==='SPM'?(semanticCatalog().mobs||[]):(semanticCatalog().npcs||[]),row=rows.find(x=>String(x.canonical_id||'').toLowerCase()===String(id).toLowerCase());if(!row){toast('Entidade mapeada não encontrada');return}let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch(e){toast('JSON inválido: '+e.message);return}const mode=$('#legacyAuthoringMode')?.value||'EDIT';if(kind==='SPM'){if(mode==='CREATE'){spec.payload=spec.payload||{};spec.payload.actors=Array.isArray(spec.payload.actors)?spec.payload.actors:[];spec.payload.actors.push({name:row.display_name||row.internal_name,weight:100})}else{spec.patch={action:'ADD_ACTOR',name:row.display_name||row.internal_name,weight:100}}addLegacySemanticRelatedRef(spec,'ACTOR',row)}else if(kind==='SPC'){const rec={name:row.display_name||row.internal_name,model_ini:row.model_file||'',server_npc:row.logical_path||'',x:0,y:0,z:0};if(mode==='CREATE'){spec.payload=spec.payload||{};spec.payload.records=Array.isArray(spec.payload.records)?spec.payload.records:[];spec.payload.records.push({index:spec.payload.records.length,...rec})}else{spec.patch={action:'ADD',index:-1,record:rec}}addLegacySemanticRelatedRef(spec,'FIXED_NPC',row)}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);toast(`${row.display_name||row.internal_name} inserido no ${kind}`)}
function renderLegacyOpsStatus(d){const tasks=d?.tasks||[];const by=id=>tasks.find(x=>x.id===id);const c=by('character_account'),p=by('items_postbox'),a=by('admin_local'),db=d?.database||a?.database||{};if($('#legacyOpsCharacterState'))$('#legacyOpsCharacterState').textContent=c?`${c.status} · userdata + userinfo`:'indisponível';if($('#legacyPostboxState'))$('#legacyPostboxState').textContent=p?`${p.status} · Postbox + serial scan`:'indisponível';if($('#legacyAdminState'))$('#legacyAdminState').textContent=a?`${a.status} · localhost + SQLite`:'indisponível';if($('#legacyAdminSummary'))$('#legacyAdminSummary').innerHTML=a?legacyTaskStatusCard(a):'<div class="empty">Admin local indisponível.</div>';const candidates=(db.candidates||[]).map(x=>({value:x.path,label:`${x.path} · ${Number(x.score||0)} tabelas conhecidas${(x.matched_tables||[]).length?' · '+x.matched_tables.join(', '):''}`}));if(db.path&&!candidates.some(x=>x.value===db.path))candidates.unshift({value:db.path,label:`${db.path} · ${db.selection_basis||'SQLite'}`});legacySelectOptions($('#legacyDatabasePath'),candidates,{placeholder:'Selecione a base SQLite'});if($('#legacyDatabasePath')&&db.path)$('#legacyDatabasePath').value=db.path;S.legacyOpsStatus=d}
async function loadLegacyOpsStatus(){try{const d=await api('/api/legacy-ops/status');renderLegacyOpsStatus(d)}catch(e){if($('#legacyAdminSummary'))$('#legacyAdminSummary').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function legacyPlanReady(saved){return saved?.apply_supported===true&&String(saved?.plan?.status||'').toUpperCase()==='READY'}
function showLegacyOpsPlan(saved){S.legacyOpsPlanId=saved?.plan_id||null;S.legacyOpsSavedPlan=saved||null;const panel=$('#legacyOpsPlanPanel'),out=$('#legacyOpsPlanResult'),state=$('#legacyOpsPlanState'),confirm=$('#legacyOpsConfirmation'),apply=$('#legacyOpsApplyBtn');if(panel)panel.classList.remove('hidden');if(out)out.textContent=legacyOpsJson(saved);const phrase=saved?.required_confirmation||'';if(confirm){confirm.value='';confirm.placeholder=phrase||'esta operação é somente plano'}if(state)state.textContent=legacyPlanReady(saved)?`READY · confirme “${phrase}”`:saved?.apply_supported===false?'PLAN ONLY · nenhuma escrita será executada':`${saved?.plan?.status||'REVIEW'} · corrija os bloqueios antes de aplicar`;if(apply){apply.disabled=!legacyPlanReady(saved);apply.textContent=legacyPlanReady(saved)?'Aplicar plano revisado':'Aplicação indisponível'}panel?.scrollIntoView({behavior:'smooth',block:'start'})}
function validateLegacyOperation(operation,p={}){const need=(v,msg)=>{if(String(v??'').trim()==='')throw new Error(msg)};switch(String(operation||'').toUpperCase()){case'CHARACTER_LEVEL':need(p.character,'Selecione o personagem');if(!Number.isFinite(Number(p.level))||Number(p.level)<1)throw new Error('Level deve ser maior ou igual a 1');break;case'CHARACTER_FIELDS':case'CHARACTER_EXPERT_FIELDS':need(p.character,'Selecione o personagem');break;case'CHARACTER_RENAME':need(p.old_name,'Selecione o personagem');need(p.new_name,'Informe o novo nome do personagem');break;case'ACCOUNT_RENAME':need(p.old_account,'Selecione a conta');need(p.new_account,'Informe o novo nome da conta');break;case'ACCOUNT_GRAPH_COPY':need(p.source_server_root,'Informe o servidor de origem');need(p.account,'Selecione a conta');break;case'ITEM_DISTRIBUTE':need(p.account,'Selecione a conta');need(p.character,'Selecione o personagem');need(p.item_code,'Selecione o item');if(Number(p.quantity)<1)throw new Error('Quantidade deve ser maior ou igual a 1');break;case'INVENTORY_ITEM_DELETE':need(p.key,'Selecione a identidade');if(Number(p.record_index)<0)throw new Error('Índice do registro inválido');break;case'INVENTORY_ITEM_BATCH_DELETE':need(p.key,'Selecione a identidade');if(!(p.record_indices||[]).length)throw new Error('Informe ao menos um índice de registro');break;case'BPRANK_MARK':need(p.char_name,'Selecione o personagem');need(p.db_path,'Selecione a base SQLite');break;case'ACCOUNT_BLOCK':need(p.account,'Selecione a conta');need(p.db_path,'Selecione a base SQLite');break;case'SOD_UPDATE':need(p.db_path,'Selecione a base SQLite');break}return true}
async function planLegacyOps(operation,payload,resultSelector){try{validateLegacyOperation(operation,payload||{});const d=await api('/api/legacy-ops/plan',{method:'POST',body:{operation,payload}});showLegacyOpsPlan(d.result);if(resultSelector)legacyOpsSet(resultSelector,d.result);toast(d.result?.apply_supported?'Plano persistido; revise antes de aplicar':'Plano gerado; operação não é aplicável por esta tela');return d.result}catch(e){const err={status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'VALIDATION_OR_REQUEST_FAILED',detail:e.message};if(resultSelector)legacyOpsSet(resultSelector,err);toast(e.message);return null}}
async function applyLegacyOpsPlan(){const id=S.legacyOpsPlanId,confirmation=$('#legacyOpsConfirmation')?.value||'';if(!id){toast('Gere e revise um plano primeiro');return}try{const d=await api('/api/legacy-ops/apply',{method:'POST',body:{plan_id:id,confirmation}});$('#legacyOpsPlanState').textContent='APPLIED · backup e verificação concluídos';legacyOpsSet('#legacyOpsPlanResult',d.result);toast('Operação aplicada com sucesso');await loadLegacyOpsStatus()}catch(e){$('#legacyOpsPlanState').textContent='APPLY FAILED';toast(e.message)}}
