function renderLegacyItem(d){const rt=d.runtime_item_contract||{},m=(rt.matches||[])[0],pc=(d.physical_client_closure||[])[0];$('#legacyItemState').textContent=`${d.code||'—'} · ${rt.status||'REVIEW'}`;if(!m){$('#legacyItemResult').innerHTML=`<div class=legacy-item-card><h3>${esc(d.code||'—')}</h3><p>${legacyStatusChip(rt.status||'RUNTIME_CODE_NOT_VERIFIED')}</p><p>Este código não existe no catálogo runtime source-verificado. A aplicação usa classificações históricas internamente quando úteis, mas você não precisa escolher prefixo/categoria manualmente.</p><p class=micro>Não crie OpenItem para um código novo até o registro sITEM estar implementado/certificado.</p></div>`;return}const paths=m.expected_client_paths||{};$('#legacyItemResult').innerHTML=`<div class=legacy-item-card><div class=legacy-item-title><h3>${esc(d.code)}</h3>${legacyStatusChip(rt.status)}</div><div class=legacy-item-columns><dl><dt>Código runtime</dt><dd><code>${esc(m.numeric_code_hex||'—')}</code></dd><dt>Pasta de ícone</dt><dd>${esc(m.item_file_path||'—')}</dd><dt>Identificador visual</dt><dd><code>${esc(m.dorp_item||'—')}</code></dd><dt>Class</dt><dd>${esc(m.class_value)}</dd><dt>Model position</dt><dd>${esc(m.set_model_posi)}</dd><dt>Sound</dt><dd>${esc(m.sound_index)}</dd><dt>Weapon class</dt><dd>${esc(m.weapon_class)}</dd></dl><dl><dt>Ícone esperado</dt><dd><code>${esc(paths.inventory_icon||'—')}</code><br>${legacyStatusChip(pc?.inventory_icon?.status)}</dd><dt>Modelo no chão</dt><dd><code>${esc(paths.drop_model_ase||'—')}</code><br>${legacyStatusChip(pc?.drop_model_ase?.status)}</dd><dt>Registro de novo sITEM</dt><dd>${legacyStatusChip(m.source_semantics?.writer_authorized?'AUTHORIZED':'BLOCKED')}</dd></dl></div></div>`}
