function legacyExplorerColumns(section){if(section==='maps')return [['status','Status'],['spm','SPM'],['actor_count','Actors'],['item_codes','Itens resolvidos'],['review_summary','O que fazer']];if(section==='definitions')return [['status','Status'],['kind','Tipo'],['definition','Definição'],['drop_item_reference_count','Drops item'],['review_summary','O que fazer']];return [['status','Status'],['code','Code'],['closures','DorpItem / assets'],['review_summary','O que fazer']]}
function legacyCell(row,key){const v=row?.[key];if(key==='status')return `${legacyStatusChip(v)}${row?.review_required?'<small class=review-inline>ver motivo →</small>':''}`;if(key==='closures')return esc((v||[]).map(x=>`${x.dorp_item||'—'} · ícone ${x.inventory_icon?.status||'—'} · chão ${x.drop_model_ase?.status||'—'}`).join(' | ')||'—');if(key==='drop_item_reference_count'){if(String(row?.kind||'').toUpperCase()!=='MONSTER')return '<span class=muted>n/a</span>';if(v==null)return '<span class=review-inline>audite novamente</span>';return `${esc(v)}${Number(v)===0?'<small class=review-inline title="0 não prova sem drop">não prova “sem drop”</small>':''}`}if(key==='review_summary')return esc(v||'Sem pendência detectada.');if(Array.isArray(v))return esc(v.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(', '));return esc(v??'—')}
function legacyReviewActions(row){const actions=row?.review_actions||[];return actions.length?`<div class=legacy-review-actions>${actions.map((a,i)=>`<button class="btn ${i===0?'primary':''}" data-legacy-review-action="${i}">${esc(a.label||'Abrir')}</button>`).join('')}</div>`:''}
async function runLegacyReviewAction(row,index){const a=(row?.review_actions||[])[Number(index)];if(!a)return;if(a.kind==='ITEM_LOOKUP'){switchLegacyTask('item');$('#legacyItemCode').value=a.code||'';await lookupLegacyItem();$('#legacyItemResult')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(a.kind==='AUTHORING'){await legacyAuthoringOpenReviewTarget(a.authoring_kind,a.path);return}toast(`Ação de review não suportada: ${a.kind}`)}
async function legacyAuthoringOpenReviewTarget(kind,path){kind=String(kind||'').toUpperCase();if(!kind||!path){toast('Target de authoring incompleto');return}switchLegacyTask(legacyTaskForKind(kind));configureLegacyEditorForTask(legacyTaskForKind(kind));$('#legacyAuthoringKind').value=kind;$('#legacyAuthoringMode').value='EDIT';$('#legacyAuthoringPath').value=path;S.legacyAuthoringManifest=null;$('#legacyAuthoringSpec').value=JSON.stringify(legacyAuthoringTemplate(),null,2);$('#legacyAuthoringState').textContent=`${kind} · carregado explicitamente do REVIEW`;syncLegacyAuthoringUi();await inspectLegacyAuthoring();$('#legacyAuthoringPanel')?.scrollIntoView({behavior:'smooth',block:'start'})}
function renderLegacyExplorerDetail(row){if(!row){$('#legacyExplorerDetail').innerHTML='<div class=empty>Selecione uma linha. REVIEW mostrará motivo e próxima ação; nada é aberto no editor automaticamente.</div>';return}const reasons=row.review_reasons||[],zhoon=(row.zhoon_references||[]),kind=String(row.kind||'').toUpperCase();let domainInfo='';if(kind==='MONSTER'){const broad=Number(row.item_reference_count||0),drops=row.drop_item_reference_count;domainInfo=`<section class=legacy-review-info><h4>Itens e drops</h4><p><b>Drops item:</b> ${drops==null?'relatório antigo; audite novamente':esc(drops)}. ${esc(row.drop_note||'')}</p><p><b>Referências de item no arquivo:</b> ${broad}. ${esc(row.item_reference_note||'')}</p>${zhoon.length?`<p><b>.zhoon:</b> ${esc(zhoon.join(', '))}. ${esc(row.zhoon_note||'')}</p>`:''}</section>`}else if(kind==='NPC'){domainInfo=`<section class=legacy-review-info><h4>Referências de item</h4><p><b>Detectadas:</b> ${Number(row.item_reference_count||0)}. ${esc(row.item_reference_note||'')}</p>${zhoon.length?`<p><b>.zhoon:</b> ${esc(zhoon.join(', '))}. ${esc(row.zhoon_note||'')}</p>`:''}</section>`}const review=row.review_required?`<section class=legacy-review-box><h4>Por que está em REVIEW?</h4>${reasons.length?reasons.map(r=>`<div class=legacy-review-reason><b>${esc(r.title||r.code)}</b><p>${esc(r.detail||'')}</p><code>${esc(r.code||'')}</code></div>`).join(''):'<p>O relatório marcou REVIEW, mas não trouxe uma causa estruturada. Audite novamente com a versão atual.</p>'}${legacyReviewActions(row)}</section>`:`<section class=legacy-review-ok><b>Sem pendência de closure detectada nesta linha.</b><p>${esc(row.review_summary||'')}</p>${legacyReviewActions(row)}</section>`;$('#legacyExplorerDetail').innerHTML=`<h3>${esc(row.code||row.spm||row.definition||'Detalhe')}</h3>${review}${domainInfo}<details class=legacy-technical-detail><summary>Detalhes técnicos</summary><pre class=legacy-json>${esc(JSON.stringify(row,null,2))}</pre></details>`;$$('[data-legacy-review-action]').forEach(b=>b.onclick=()=>runLegacyReviewAction(row,b.dataset.legacyReviewAction))}
async function loadLegacyExplorer(){const section=$('#legacyExplorerSection')?.value||'items',q=$('#legacyExplorerSearch')?.value||'',status=$('#legacyExplorerStatus')?.value||'';try{const d=await api(`/api/legacy-management/report?section=${encodeURIComponent(section)}&q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}&limit=200`);$('#legacyExplorerState').textContent=d.status==='PASS'?`${d.filtered_rows}/${d.total_rows} registros`:d.status;const cols=legacyExplorerColumns(section);$('#legacyExplorerHead').innerHTML='<tr>'+cols.map(x=>`<th>${esc(x[1])}</th>`).join('')+'</tr>';$('#legacyExplorerRows').innerHTML=(d.rows||[]).map((r,i)=>`<tr data-legacy-row="${i}">${cols.map(([k])=>`<td>${legacyCell(r,k)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}"><div class=empty>${d.status==='NO_REPORT'?'Execute a auditoria Management para gerar o relatório.':'Nenhum registro com os filtros atuais.'}</div></td></tr>`;S.legacyRows=d.rows||[];$$('[data-legacy-row]').forEach(tr=>tr.onclick=async()=>{const row=S.legacyRows[Number(tr.dataset.legacyRow)];$$('[data-legacy-row]').forEach(x=>x.classList.toggle('selected',x===tr));renderLegacyExplorerDetail(row)})}catch(e){$('#legacyExplorerState').textContent='Erro';toast(e.message)}}
function legacyAuthoringDefaultPath(kind){return ({ITEM:'GameServer/OpenItem/WA121.txt',MONSTER:'GameServer/Monster/NewMonster.inf',NPC:'GameServer/NPC/NewNPC.npc',SPM:'GameServer/Field/field.spm',SPP:'GameServer/Field/field.spp',SPC:'GameServer/Field/field.spc'})[kind]||''}
function legacyAuthoringTemplate(){const kind=$('#legacyAuthoringKind')?.value||'ITEM',mode=$('#legacyAuthoringMode')?.value||'EDIT',path=$('#legacyAuthoringPath')?.value.trim()||legacyAuthoringDefaultPath(kind),selectedValue=kind==='ITEM'?($('#legacyItemCode')?.value||''):($('#legacyAuthoringItemCode')?.value||''),selectedItem=legacySelectedItem(selectedValue),selectedCode=selectedItem?.code||selectedValue;const base={kind,mode,path};if(mode==='CREATE'){if(kind==='ITEM')Object.assign(base,{fields:{name:selectedItem?.display_name||selectedItem?.name||'',code:selectedCode||'',weight:1,price:1}});else if(kind==='MONSTER')Object.assign(base,{payload:{fields:{name:'Novo Monster',model_file:'char/monster/new/new.ini',level:1,life:100,experience:1,attack_damage:[1,2],attack_speed:[1,1],attack_range:40,attack_rating:10,defence:5,absorption:0,sight:300},drops:[]}});else if(kind==='NPC')Object.assign(base,{payload:{fields:{name:'Novo NPC',model_file:'char/npc/new/new.ini',shop:true},dialogs:[],shops:{weapon:[],defence:[],etc:[]}}});else if(kind==='SPM')Object.assign(base,{payload:{actors:[{name:'Cuepy',weight:100}],max_actor:10,delay_seconds:10}});else if(kind==='SPP')Object.assign(base,{payload:{records:[{index:0,state:1,x:0,z:0}]}});else if(kind==='SPC')Object.assign(base,{payload:{records:[{index:0,name:'NEW_NPC',model_ini:'char/npc/new/new.ini',server_npc:'GameServer/NPC/NewNPC.npc',x:0,y:0,z:0}]}})}else{if(kind==='ITEM')Object.assign(base,{patch:{set:{price:1}}});else if(kind==='MONSTER')Object.assign(base,{patch:{set:{experience:1000}}});else if(kind==='NPC')Object.assign(base,{patch:{shops:{weapon:[],defence:[],etc:[]},dialogs:[]}});else if(kind==='SPM')Object.assign(base,{patch:{action:'ADD_ACTOR',name:'Cuepy',weight:100}});else if(kind==='SPP')Object.assign(base,{patch:{records:[{index:0,state:1,x:0,z:0}]}});else if(kind==='SPC')Object.assign(base,{patch:{action:'ADD',index:0,record:{name:'NEW_NPC',model_ini:'char/npc/new/new.ini',server_npc:'GameServer/NPC/NewNPC.npc',x:0,y:0,z:0}}})}return base}
function loadLegacyAuthoringTemplate(){const kind=$('#legacyAuthoringKind').value;if(!$('#legacyAuthoringPath').value.trim())$('#legacyAuthoringPath').value=legacyAuthoringDefaultPath(kind);S.legacyAuthoringManifest=null;$('#legacyAuthoringSpec').value=JSON.stringify(legacyAuthoringTemplate(),null,2);$('#legacyAuthoringResult').textContent=`Template ${kind}/${$('#legacyAuthoringMode').value} carregado. Ajuste e use Stage.`;syncLegacyAuthoringUi()}
async function inspectLegacyAuthoring(){const kind=$('#legacyAuthoringKind').value,path=$('#legacyAuthoringPath').value.trim();if(!path){toast('Informe o path do arquivo');return}S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();try{const d=await api('/api/legacy-authoring/inspect?'+new URLSearchParams({kind,path}));$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);$('#legacyAuthoringState').textContent=`${kind} · ${d.result.status}`;if(d.result.exists&&d.result.source_sha256){let spec;try{spec=JSON.parse($('#legacyAuthoringSpec').value||'{}')}catch{spec=legacyAuthoringTemplate()}spec.kind=kind;spec.mode='EDIT';spec.path=path;spec.expected_sha256=d.result.source_sha256;$('#legacyAuthoringMode').value='EDIT';$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2)}syncLegacyAuthoringUi();toast(d.result.exists?'Arquivo carregado para authoring':'Target novo; use CREATE')}catch(e){$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'INSPECT_FAILED',detail:e.message},null,2);toast(e.message)}}
async function stageLegacyAuthoring(){if(!S.boot.write_armed){$('#modal').classList.remove('hidden');toast('Arme workspace/build antes de criar o draft');return}let spec;try{spec=JSON.parse($('#legacyAuthoringSpec').value)}catch(e){toast('JSON inválido: '+e.message);return}spec.kind=$('#legacyAuthoringKind').value;spec.mode=$('#legacyAuthoringMode').value;spec.path=$('#legacyAuthoringPath').value.trim();S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();try{const d=await api('/api/legacy-authoring/stage',{method:'POST',body:{spec}});const r=d.result||{},m=r.manifest||{};S.legacyAuthoringManifest=m.manifest||m?.manifest?.manifest||r.manifest_path||null;if(!S.legacyAuthoringManifest)throw new Error('Stage concluído sem manifest publicável');$('#legacyAuthoringResult').textContent=JSON.stringify(r,null,2);$('#legacyAuthoringState').textContent=`${spec.kind} · STAGED`;saveLegacyEditorState();syncLegacyAuthoringUi();toast('Authoring staged em pt_build; revise o manifest antes de publicar')}catch(e){S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'STAGE_FAILED',detail:e.message},null,2);toast(e.message)}}
async function deployLegacyAuthoring(mode){try{if(mode==='status'){const d=await api('/api/asset-compiler/status');$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);return}if(mode==='publish'&&!S.legacyAuthoringManifest){toast('Faça Stage nesta tarefa antes de publicar');syncLegacyAuthoringUi();return}if(!(await armAssetDeploy()))return;const msg=mode==='publish'?'Publicar o manifest staged desta tarefa?\n\nPreflight de hashes, backup e verificação pós-write serão executados.':'Restaurar o último bundle de authoring?\n\nDrift externo bloqueia o restore.';if(!confirm(msg)){S.boot.server_deploy_armed=false;return}const body={};if(mode==='publish')body.manifest=S.legacyAuthoringManifest;const d=await api('/api/asset-compiler/'+mode,{method:'POST',body});S.boot.server_deploy_armed=false;S.boot.server_deploy_armed_until=0;$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);$('#legacyAuthoringState').textContent=mode==='publish'?'APPLIED_VERIFIED':'RESTORED_VERIFIED';if(mode==='publish'){S.legacyAuthoringManifest=null;saveLegacyEditorState()}toast(mode==='publish'?'Authoring publicado; valide no jogo':'Authoring restaurado')}catch(e){S.boot.server_deploy_armed=false;S.boot.server_deploy_armed_until=0;$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'DEPLOY_FAILED',detail:e.message},null,2);toast(e.message)}finally{syncLegacyAuthoringUi()}}

let particleSearchTimer=null;
async function loadParticleAssets(){
  if(!$('#particleRows'))return;
  const q=$('#particleSearch')?.value.trim()||'';
  try{const d=await api('/api/particles?q='+encodeURIComponent(q));const rows=d.items||[];$('#particleCount').textContent=`${rows.length.toLocaleString()} .part`;$('#particleRows').innerHTML=rows.length?rows.map((r,i)=>`<tr data-particle-row="${i}"><td class="path" title="${esc(r.asset)}">${esc(r.asset)}</td><td>${fmtBytes(r.size)}</td></tr>`).join(''):'<tr><td colspan="2" class="empty">Nenhum .part encontrado.</td></tr>';$$('[data-particle-row]').forEach(tr=>tr.onclick=()=>selectParticle(rows[Number(tr.dataset.particleRow)].asset))}catch(e){$('#particleRows').innerHTML=`<tr><td colspan="2" class="empty">${esc(e.message)}</td></tr>`;$('#particleCount').textContent='Erro'}
}
async function selectParticle(asset){
  try{const d=await api('/api/particles/inspect?asset='+encodeURIComponent(asset));S.particle=asset;renderParticleDetail(d.particle)}catch(e){toast(e.message)}
}
function renderParticleDetail(d){
  const fields=d.occurrences||[];const draft=d.draft||{};
  $('#particleDetail').innerHTML=`<div class="panel" style="margin:0"><div class="panel-title"><strong>${esc(d.asset)}</strong><span>${esc(d.authoring_status)} · ${esc(d.parse_status)}</span></div><div class="micro">SHA-256 ${esc(d.source_sha256)} · EOL ${esc(d.eol)} · client/server source write disabled</div><div class="server-explorer-table" style="max-height:46vh;overflow:auto;margin-top:10px"><table><thead><tr><th>Linha</th><th>Selector</th><th>Tipo</th><th>Valor / staging</th></tr></thead><tbody>${fields.map((o,i)=>{const sel=`${o.canonical_key}[${o.occurrence}]`;return `<tr><td>${Number(o.line||0)}</td><td><code>${esc(sel)}</code></td><td>${esc(o.value_kind||'—')}</td><td>${o.editable&&d.authoring_status==='EDITABLE_STAGING'?`<div style="display:flex;gap:6px"><input data-particle-value="${i}" value="${esc(o.value)}" style="min-width:220px;flex:1"><button class="btn small" data-particle-stage="${i}" data-selector="${esc(sel)}">Stage</button></div>`:esc(o.value)}</td></tr>`}).join('')}</tbody></table></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button id="particleVerify" class="btn">Verificar draft</button><button id="particlePreviewPlan" class="btn">Gerar plano de preview</button><button id="particlePreviewRun" class="btn primary">Gerar preview Blender</button></div><pre id="particleOutput" class="micro" style="white-space:pre-wrap;max-height:280px;overflow:auto">Draft: ${esc(JSON.stringify(draft,null,2))}</pre><img id="particlePreviewImage" hidden style="max-width:512px;width:100%;border-radius:6px"></div>`;
  $$('[data-particle-stage]').forEach(b=>b.onclick=()=>stageParticle(b.dataset.selector,$(`[data-particle-value="${b.dataset.particleStage}"]`).value));$('#particleVerify').onclick=particleVerify;$('#particlePreviewPlan').onclick=particlePreviewPlan;$('#particlePreviewRun').onclick=particlePreviewRun;
}
async function stageParticle(selector,value){try{const d=await api('/api/particles/stage-edit',{method:'POST',body:{asset:S.particle,selector,value}});toast('Draft de partícula atualizado em pt_build');await selectParticle(S.particle);return d}catch(e){toast(e.message)}}
async function particleVerify(){try{const d=await api('/api/particles/draft-verify?asset='+encodeURIComponent(S.particle));$('#particleOutput').textContent=JSON.stringify(d.result,null,2)}catch(e){$('#particleOutput').textContent=e.message}}
async function particlePreviewPlan(){const b=$('#particlePreviewPlan');if(!S.particle){$('#particleOutput').textContent='Selecione um arquivo .part primeiro.';return}b.disabled=true;$('#particleOutput').textContent='Gerando plano semântico de preview…';try{const d=await api('/api/particles/preview-plan',{method:'POST',body:{asset:S.particle}}),r=d.result||{};const blender=r.blender_ready?'Blender: READY':`Blender: indisponível (${r.blender_detail||'execute pt-asset-tool dependencies'})`;$('#particleOutput').textContent=`Plano: PASS\nAsset: ${r.asset||S.particle}\nEventos: ${r.event_count??0}\nTexturas ausentes: ${r.missing_texture_reference_count??0}\nWarnings semânticos: ${r.semantic_warning_count??0}\n${blender}\nArquivo: ${r.plan_path||'—'}\n\n${JSON.stringify(r,null,2)}`;toast('Plano de preview gerado')}catch(e){$('#particleOutput').textContent='Falha ao gerar plano de preview:\n'+e.message;toast(e.message)}finally{b.disabled=false}}
async function particlePreviewRun(){const b=$('#particlePreviewRun');if(!S.particle){$('#particleOutput').textContent='Selecione um arquivo .part primeiro.';return}b.disabled=true;$('#particleOutput').textContent='Executando Blender em background. O primeiro preview pode demorar…';try{const d=await api('/api/particles/preview-run',{method:'POST',body:{asset:S.particle}}),r=d.result||{};$('#particleOutput').textContent=JSON.stringify(r,null,2);const renders=r.render_files||r.report?.render_files||[];const img=$('#particlePreviewImage');if(renders.length){img.src='/api/particles/preview-image?path='+encodeURIComponent(renders[Math.min(1,renders.length-1)]);img.hidden=false}else{img.hidden=true;img.removeAttribute('src');if(r.status!=='PASS')toast('Blender não gerou preview; veja o diagnóstico abaixo')}}catch(e){$('#particleOutput').textContent='Falha no preview Blender:\n'+e.message;toast(e.message)}finally{b.disabled=false}}

